addpath('euler');
addpath('transfer_function');

clear;
clc;
close all;



%Run euler model
[time, euler_position] = euler_sim(); %[output:95587283]

%Run transfer function
[~, tf_position] = tf_model(time);

% plotting euler model vs transfer function position values
fig1 = figure; %[output:072fbb0b]
plot(time, euler_position, 'b-', 'LineWidth', 1.5); %[output:072fbb0b]
hold on; %[output:072fbb0b]
plot(time, tf_position, 'r--', 'LineWidth', 1.5); %[output:072fbb0b]

xlabel('Time (s)'); %[output:072fbb0b]
ylabel('Position (m)'); %[output:072fbb0b]
title('Euler Model vs. Transfer Function'); %[output:072fbb0b]

legend('Euler Model', 'Transfer Function', 'Location', 'best'); %[output:072fbb0b]

grid on; %[output:072fbb0b]
hold off; %[output:072fbb0b]

% error calculation and documentation
euler_position = euler_position(:);
tf_position = tf_position(:);
error_values = abs(euler_position - tf_position);
max_error = max(error_values);
fprintf('Maximum error: %.6f m/n', max_error); %[output:560f0efe]

% error plotting
fig2 = figure; %[output:19b22d8d]
plot(time, error_values, 'LineWidth', 1.5); %[output:19b22d8d]
xlabel('Time (s)'); %[output:19b22d8d]
ylabel('Absolute Position Error (m)'); %[output:19b22d8d]
title('Euler vs. Transfer Function Error'); %[output:19b22d8d]
grid on; %[output:19b22d8d]

% exporting plots
scriptFolder = pwd; %[output:0961eeb7]
imagesFolder = fullfile(scriptFolder, '..', 'images');

exportgraphics(fig1, fullfile(imagesFolder, "eulervstransfer.png"), 'Resolution', 300); %[output:072fbb0b]
exportgraphics(fig2, fullfile(imagesFolder, "errorplot.png"), 'Resolution', 300); %[output:19b22d8d]

